import type { Role } from '../app/Role'
import type { Documentation, TableColumn } from './Column'
import type { Record } from './Record'

export type TableName = keyof Now.Internal.Tables

export type Schema<T extends TableName> = Now.Internal.Tables[T] extends { schema: infer S extends object }
    ? S
    : TableColumn

export type FullSchema<T extends TableName> = Now.Internal.Tables[T]['extends'] extends infer E extends string
    ? Schema<T> & FullSchema<E>
    : Schema<T>

export type LicensingConfig =
    | {
          /** The model for tracking subscription usage. */
          licenseModel?: 'none' | 'fulfiller' | 'producer'
          /** A filter query that determines whether a user owns a record for the fulfiller model. */
          ownerCondition?: string
          /** A filter query that determines conditions for counting operations toward a subscription. */
          licenseCondition?: string
          /** Flag that indicates whether to disallow updates by users who aren't subscribed to the application. */
          isFulfillment?: boolean
          /** Flag that indicates whether a subscription is required to delete records for tables with the producer model. */
          opDelete?: boolean
          /** Flag that indicates whether a subscription is required to update records for tables with the producer model. */
          opUpdate?: boolean
          /** Flag that indicates whether a subscription is required to insert records for tables with the producer model. */
          opInsert?: boolean
          /** A list of roles for which any operations on records in the table count toward the subscription. */
          licenseRoles?: string[]
          /**@deprecated use `licenseModel` instead  */
          license_model?: never
          /** @deprecated use `ownerCondition` instead */
          owner_condition?: never
          /** @deprecated use `licenseCondition` instead */
          license_condition?: never
          /** @deprecated use `isFulfillment` instead */
          is_fulfillment?: never
          /** @deprecated use `opDelete` instead */
          op_delete?: never
          /** @deprecated use `opUpdate` instead */
          op_update?: never
          /** @deprecated use `opInsert` instead */
          op_insert?: never
          /** @deprecated use `licenseRoles` instead */
          license_roles?: never
      }
    | {
          /**@deprecated use `licenseModel` instead  */
          license_model?: 'none' | 'fulfiller' | 'producer'
          /** @deprecated use `ownerCondition` instead */
          owner_condition?: string
          /** @deprecated use `licenseCondition` instead */
          license_condition?: string
          /** @deprecated use `isFulfillment` instead */
          is_fulfillment?: boolean
          /** @deprecated use `opDelete` instead */
          op_delete?: boolean
          /** @deprecated use `opUpdate` instead */
          op_update?: boolean
          /** @deprecated use `opInsert` instead */
          op_insert?: boolean
          /** @deprecated use `licenseRoles` instead */
          license_roles?: string[]
          /** The model for tracking subscription usage. */
          licenseModel?: never
          /** A filter query that determines whether a user owns a record for the fulfiller model. */
          ownerCondition?: never
          /** A filter query that determines conditions for counting operations toward a subscription. */
          licenseCondition?: never
          /** Flag that indicates whether to disallow updates by users who aren't subscribed to the application. */
          isFulfillment?: never
          /** Flag that indicates whether a subscription is required to delete records for tables with the producer model. */
          opDelete?: never
          /** Flag that indicates whether a subscription is required to update records for tables with the producer model. */
          opUpdate?: never
          /** Flag that indicates whether a subscription is required to insert records for tables with the producer model. */
          opInsert?: never
          /** A list of roles for which any operations on records in the table count toward the subscription. */
          licenseRoles?: never
      }

/** @interface */
export type Table<
    S extends TableColumn = TableColumn,
    E extends TableName | undefined = TableName | undefined,
> = Now.Internal.WithMetadata<
    {
        /** Array of column references that define the table's schema */
        schema: S
    } & (
        | {
              /**
               * The name of an existing table to augment by adding columns
               */
              augments: string
              name?: never
              extends?: never
              label?: never
              display?: never
              extensible?: never
              actions?: never
              audit?: never
              attributes?: never
              index?: never
              readOnly?: never
              textIndex?: never
              allowWebServiceAccess?: never
              allowNewFields?: never
              allowUiActions?: never
              allowClientScripts?: never
              licensingConfig?: never
              liveFeed?: never
              accessibleFrom?: never
              callerAccess?: never
              autoNumber?: never
              scriptableTable?: never
              createAccessControls?: never
              userRole?: never
              read_only?: never
              text_index?: never
              allow_web_service_access?: never
              allow_new_fields?: never
              allow_ui_actions?: never
              allow_client_scripts?: never
              licensing_config?: never
              live_feed?: never
              accessible_from?: never
              caller_access?: never
              auto_number?: never
              scriptable_table?: never
          }
        | ({
              augments?: never
              /** Name of the table. Must be lowercase and include the application scope. */
              name: string
              /** The name of any other table on which this table is based. */
              extends?: E
              /** A unique label for the table on list and form views. */
              label?: string | Documentation[]
              /** Default display column. Use a column name from the schema. */
              display?: string
              /** Indicates whether other tables can extend this table. */
              extensible?: boolean
              /** List of access options for the table. */
              actions?: ('read' | 'update' | 'delete' | 'create')[]
              /** Indicates whether to track the creation, update, and deletion of all records in the table. */
              audit?: boolean
              /** Pairs of any supported dictionary attributes (sys_schema_attribute). */
              attributes?: { [key: string]: string | number | boolean }
              /** A list of column references to generate indexes in the metadata XML of the table. */
              index?: {
                  /** Name of the index. */
                  name: string
                  /** Whether the index is unique. */
                  unique: boolean
                  /** Column references that make up the index. */
                  element: (keyof S)[] | keyof S | (string & {}) | (string & {})[]
              }[]
          } & (
              | {
                    /** Indicates whether users can edit fields in the table. */
                    readOnly?: boolean
                    /** Indicates whether search engines index the text in a table. */
                    textIndex?: boolean
                    /** Indicates whether web services can make calls to the table. */
                    allowWebServiceAccess?: boolean
                    /** Indicates whether to allow design time configuration of new fields on the table from other application scope. */
                    allowNewFields?: boolean
                    /** Indicates whether to allow design time configuration of UI Actions on the table from other application scopes. */
                    allowUiActions?: boolean
                    /** Indicates whether to allow design time configuration of client scripts on the table from other application scopes. */
                    allowClientScripts?: boolean
                    /** Configuration for table licensing. */
                    licensingConfig?: LicensingConfig
                    /** Indicates if live feeds are available for records in the table. */
                    liveFeed?: boolean
                    /** Application scopes that can access the table. */
                    accessibleFrom?: 'public' | 'package_private'
                    /** Access level for cross-scope requests. */
                    callerAccess?: 'none' | 'tracking' | 'restricted'
                    /**
                     * Auto-numbering configuration for the table.
                     * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
                     */
                    autoNumber?: {
                        prefix?: string
                        number?: number
                        numberOfDigits?: number
                    }
                    /** Indicates whether the table is a remote table that uses data retrieved from an external source. */
                    scriptableTable?: boolean
                    /** Indicates whether to create access controls when the table is created. */
                    createAccessControls?: boolean
                    /**
                     * Role used to wire the table's auto-generated access controls. Accepts a role name
                     * (created on-demand via the platform's `dynamic_creation` script if it does not yet
                     * exist) or a reference to an existing `sys_user_role` record. When omitted, the
                     * platform falls back to the parent application's `user_role`.
                     *
                     * Only takes effect when `createAccessControls` is `true`.
                     */
                    userRole?: string | Role | Record<'sys_user_role'>
                    /** @deprecated Use readOnly instead */
                    read_only?: never
                    /** @deprecated Use textIndex instead */
                    text_index?: never
                    /** @deprecated Use allowWebServiceAccess instead */
                    allow_web_service_access?: never
                    /** @deprecated Use allowNewFields instead */
                    allow_new_fields?: never
                    /** @deprecated Use allowUiActions instead */
                    allow_ui_actions?: never
                    /** @deprecated Use allowClientScripts instead */
                    allow_client_scripts?: never
                    /** @deprecated Use licensingConfig instead */
                    licensing_config?: never
                    /** @deprecated Use liveFeed instead */
                    live_feed?: never
                    /** @deprecated Use accessibleFrom instead */
                    accessible_from?: never
                    /** @deprecated Use callerAccess instead */
                    caller_access?: never
                    /** @deprecated use scriptableTable instead */
                    scriptable_table?: never
                    /** @deprecated Use autoNumber instead */
                    auto_number?: never
                }
              | {
                    /** @deprecated Use readOnly instead */
                    read_only?: boolean
                    /** @deprecated Use textIndex instead */
                    text_index?: boolean
                    /** @deprecated Use allowWebServiceAccess instead */
                    allow_web_service_access?: boolean
                    /** @deprecated Use allowNewFields instead */
                    allow_new_fields?: boolean
                    /** @deprecated Use allowUiActions instead */
                    allow_ui_actions?: boolean
                    /** @deprecated Use allowClientScripts instead */
                    allow_client_scripts?: boolean
                    /** @deprecated Use licensingConfig instead */
                    licensing_config?: LicensingConfig
                    /** @deprecated Use liveFeed instead */
                    live_feed?: boolean
                    /** @deprecated Use accessibleFrom instead */
                    accessible_from?: 'public' | 'package_private'
                    /** @deprecated Use callerAccess instead */
                    caller_access?: 'none' | 'tracking' | 'restricted'
                    /** @deprecated use scriptableTable instead */
                    scriptable_table?: boolean
                    /** @deprecated Use autoNumber instead */
                    auto_number?: {
                        prefix?: string
                        number?: number
                        number_of_digits?: number
                    }
                    /** Indicates whether users can edit fields in the table. */
                    readOnly?: never
                    /** Indicates whether search engines index the text in a table. */
                    textIndex?: never
                    /** Indicates whether web services can make calls to the table. */
                    allowWebServiceAccess?: never
                    /** Indicates whether to allow design time configuration of new fields on the table from other application scope. */
                    allowNewFields?: never
                    /** Indicates whether to allow design time configuration of UI Actions on the table from other application scopes. */
                    allowUiActions?: never
                    /** Indicates whether to allow design time configuration of client scripts on the table from other application scopes. */
                    allowClientScripts?: never
                    /** Configuration for table licensing. */
                    licensingConfig?: never
                    /** Indicates if live feeds are available for records in the table. */
                    liveFeed?: never
                    /** Application scopes that can access the table. */
                    accessibleFrom?: never
                    /** Access level for cross-scope requests. */
                    callerAccess?: never
                    /** Indicates whether the table is a remote table that uses data retrieved from an external source. */
                    scriptableTable?: never
                    /** Indicates whether to create access controls when the table is created. */
                    createAccessControls?: never
                    /**
                     * Role used to wire the table's auto-generated access controls. Accepts a role name
                     * (created on-demand via the platform's `dynamic_creation` script if it does not yet
                     * exist) or a reference to an existing `sys_user_role` record. When omitted, the
                     * platform falls back to the parent application's `user_role`.
                     *
                     * Only takes effect when `createAccessControls` is `true`.
                     */
                    userRole?: never
                    /**
                     * Auto-numbering configuration for the table.
                     * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
                     */
                    autoNumber?: never
                }
          ))
    )
>

/**
 * Creates a table in a scoped application (`sys_db_object`).
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 * @group Table
 */
export function Table<const S extends TableColumn, const E extends TableName, const T extends Table<S, E>>(
    table: T & Table<S, E>
): T {
    return table
}

export type SystemColumns =
    | 'sys_created_on'
    | 'sys_created_by'
    | 'sys_updated_by'
    | 'sys_updated_on'
    | 'sys_mod_count'
    | 'sys_id'

// TODO: Find a way to provide typeahead support for dot-walking through reference columns WITHOUT huge performance cost
export type TableSchemaDotWalk<T extends TableName> =
    `${string & (keyof FullSchema<T> | SystemColumns)}${'' | `.${string}`}`
